[asy]
size(250);
defaultpen(fontsize(9));

fill((0,0)--(40,0)--(40,20)--(0,20)--cycle,lightgray);

draw((0,20)--(0,0)--(40,0));

draw((-0.5,2)--(40,2));
draw((-0.5,4)--(40,4));
draw((-0.5,6)--(40,6));
draw((-0.5,8)--(40,8));
draw((-0.5,10)--(40,10));
draw((-0.5,12)--(40,12));
draw((-0.5,14)--(40,14));
draw((-0.5,16)--(40,16));
draw((-0.5,18)--(40,18));
draw((-0.5,20)--(40,20));

filldraw((2.5,0)--(2.5,12.5)--(7.5,12.5)--(7.5,0)--cycle,lightblue);

draw((10,0)--(10,-0.5));
draw((20,0)--(20,-0.5));
